/**
 * Smart Trip Planner → AI prompt compiler.
 *
 * Only constructs the user's request. Every itinerary and suggestion remains
 * genuinely generated by the existing TourMate backend; nothing is prefilled
 * with a canned attraction, schedule, ticket price, or AI response.
 */
export const TRIP_STYLES = Object.freeze(["balanced", "relaxed", "adventure", "culture", "family"]);
export const TRIP_FOOD = Object.freeze(["none", "vegetarian", "vegan", "halal"]);
export const TRIP_INTERESTS = Object.freeze(["heritage", "nature", "food", "shopping", "photography", "hidden"]);
export const TRIP_CURRENCIES = Object.freeze(["CNY", "SGD", "INR", "USD", "EUR"]);

function cleanText(value, maxLength) {
  if (typeof value !== "string") return "";
  return value.normalize("NFKC").replace(/[\u0000-\u001f\u007f]/gu," ").replace(/\s+/gu," ").trim().slice(0,maxLength);
}
function numberRange(value, min, max, fallback) {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed >= min && parsed <= max ? parsed : fallback;
}
function validDate(value) {
  if (!value) return "";
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/u.test(value)) return "";
  const date = new Date(value+"T00:00:00Z");
  return Number.isFinite(date.valueOf()) && date.toISOString().slice(0,10) === value ? value : "";
}

/** @throws {Error} if a destination is absent or a requested budget is invalid. */
export function buildSmartTripPrompt(input = {}, language = "en") {
  const zh = language === "zh";
  const destination = cleanText(input.destination, 80);
  if (!destination) throw new Error(zh ? "请输入中国旅行目的地。" : "Enter a destination in China.");

  const origin = cleanText(input.origin, 80);
  const notes = cleanText(input.notes, 170);
  const days = numberRange(input.days, 1, 21, 4);
  const travelers = numberRange(input.travelers, 1, 12, 2);
  const style = TRIP_STYLES.includes(input.style) ? input.style : "balanced";
  const food = TRIP_FOOD.includes(input.food) ? input.food : "none";
  const currency = TRIP_CURRENCIES.includes(input.currency) ? input.currency : "CNY";
  const startDate = validDate(input.startDate);
  const interests = Array.isArray(input.interests)
    ? [...new Set(input.interests.filter(item => TRIP_INTERESTS.includes(item)))].slice(0,4)
    : [];
  const budgetValue = cleanText(String(input.budget ?? ""), 20);
  const budget = budgetValue === "" ? null : Number(budgetValue);
  if (budgetValue && (!Number.isInteger(budget) || budget <= 0 || budget > 1000000)) {
    throw new Error(zh ? "预算需为 1 到 1,000,000 的整数。" : "Budget must be a whole number between 1 and 1,000,000.");
  }

  const styles = {
    balanced: ["balanced sightseeing and downtime","景点游览与休息兼顾"],
    relaxed: ["relaxed, with fewer transfers","轻松慢游，减少奔波"],
    adventure: ["active and adventurous","丰富户外和探索体验"],
    culture: ["cultural immersion and local heritage","深入当地文化和历史"],
    family: ["family-friendly with comfortable pacing","亲子友好且节奏舒适"]
  };
  const foods = {
    none: ["no specific food restrictions","无特别饮食限制"],
    vegetarian: ["strictly vegetarian meal options","严格素食用餐选择"],
    vegan: ["vegan meal options","纯素用餐选择"],
    halal: ["halal-friendly food options, with verification where necessary","清真友好餐饮，并提醒核实"]
  };
  const interestLabels = {
    heritage: ["history and heritage","历史文化"],
    nature: ["natural scenery","自然风光"],
    food: ["local food","当地美食"],
    shopping: ["shopping and markets","购物与集市"],
    photography: ["photography","摄影打卡"],
    hidden: ["less-touristy places","小众目的地"]
  };

  const prompt = zh
    ? [
      "请根据以下实际偏好，为我原创规划一份详细、可实行的中国旅行行程。",
      "目的地："+destination+"。",
      origin ? "出发地："+origin+"。" : "",
      "时长："+days+"天。",
      startDate ? "计划出发日期："+startDate+"。" : "",
      "同行人数："+travelers+"人。",
      budget !== null ? "每人总预算："+budget+" "+currency+"。" : "",
      "旅行风格："+styles[style][1]+"。",
      "饮食需求："+foods[food][1]+"。",
      interests.length ? "兴趣重点："+interests.map(id=>interestLabels[id][1]).join("、")+"。" : "",
      notes ? "其他要求："+notes+"。" : "",
      "请按天安排景点、合理的交通顺序、用餐建议和休息缓冲。注明需要通过官方渠道核实的动态票务、价格与时刻信息；不要声称已实时查询或完成预订。"
    ].filter(Boolean).join("\n")
    : [
      "Create an original, practical day-by-day itinerary for my trip within China using the following preferences.",
      "Destination: "+destination+".",
      origin ? "Starting from: "+origin+"." : "",
      "Duration: "+days+" days.",
      startDate ? "Planned departure date: "+startDate+"." : "",
      "Group: "+travelers+" traveler"+(travelers===1?"":"s")+".",
      budget !== null ? "Total budget per person: "+budget+" "+currency+"." : "",
      "Travel style: "+styles[style][0]+".",
      "Food: "+foods[food][0]+".",
      interests.length ? "Interests: "+interests.map(id=>interestLabels[id][0]).join(", ")+"." : "",
      notes ? "Additional constraints: "+notes+"." : "",
      "Build realistic daily routes with sensible transport, meals, and rest buffers. Point out changing schedules, fares and ticket requirements that I should verify through official channels. Do not claim to have made bookings or checked live availability."
    ].filter(Boolean).join("\n");

  if (prompt.length > 1500) throw new Error(zh ? "请缩短部分要求。" : "Please shorten the trip details.");
  return prompt;
}
